using System.ComponentModel;
using System.Net.Http.Json;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

namespace McpServer.Tools;

[McpServerToolType]
public sealed class ExternalApiTool
{
    [McpServerTool("fetch_data"), Description("Fetches data from an external API by resource ID.")]
    public static async Task<string> FetchDataAsync(
        IHttpClientFactory httpClientFactory,
        ILogger<ExternalApiTool> logger,
        [Description("The resource ID to fetch")] string resourceId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching resource {ResourceId}", resourceId);

        using var client = httpClientFactory.CreateClient("ExternalApi");
        var response = await client.GetAsync($"resources/{resourceId}", cancellationToken);

        if (!response.IsSuccessStatusCode)
        {
            var error = $"API returned {(int)response.StatusCode} {response.ReasonPhrase}";
            logger.LogWarning("{Error}", error);
            return error;
        }

        var body = await response.Content.ReadAsStringAsync(cancellationToken);
        logger.LogInformation("Successfully fetched resource {ResourceId} ({Length} chars)",
            resourceId, body.Length);
        return body;
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

namespace McpServer.Prompts;

[McpServerPromptType]
public sealed class SummarizationPrompt
{
    [McpServerPrompt("summarize"), Description("Summarizes the provided text concisely.")]
    public static IList<McpServerPromptMessage> Summarize(
        [Description("The text to summarize")] string text,
        [Description("Desired summary style: brief, detailed, or bullet-points")] string style = "brief")
    {
        var systemInstruction = style switch
        {
            "detailed" => "Provide a thorough summary covering all key points.",
            "bullet-points" => "Summarize the text as a concise bullet-point list.",
            _ => "Provide a brief one-paragraph summary."
        };

        return
        [
            new McpServerPromptMessage
            {
                Role = McpServerPromptMessageRole.User,
                Content = new() { Text = $"{systemInstruction}\n\n---\n\n{text}", Type = "text" }
            }
        ];
    }
}

